    [[nodiscard]] std::uint64_t concat(std::uint64_t left,
                                     std::uint64_t right,
                                     std::size_t right_length) const {
#ifndef SKIP_RUNTIME_CHECKS
        if (right_length > size()) {
            throw std::out_of_range("RollingHash: concatenation length");
