    [[nodiscard]] bool equal(std::size_t l, std::size_t r,
                             const RollingHash& other,
                             std::size_t ol, std::size_t orr) const {
#ifndef SKIP_RUNTIME_CHECKS
        check_range(l, r);
        other.check_range(ol, orr);
