#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <new>
#include <string>
#include <utility>
namespace allocation_probe {
struct alignas(std::max_align_t) Header { std::size_t bytes; };
std::size_t count=0,bytes=0,live=0,peak=0;bool tracking=false;
void reset(){count=0;bytes=0;peak=live;}
}
void* operator new(std::size_t n){using namespace allocation_probe;void*p=std::malloc(sizeof(Header)+n);if(!p)throw std::bad_alloc();auto*h=static_cast<Header*>(p);h->bytes=tracking?n:0;if(tracking){++count;bytes+=n;live+=n;if(live>peak)peak=live;}return h+1;}
void operator delete(void*p)noexcept{if(!p)return;using namespace allocation_probe;auto*h=static_cast<Header*>(p)-1;live-=h->bytes;std::free(h);}
void operator delete(void*p,std::size_t)noexcept{::operator delete(p);}
void* operator new[](std::size_t n){return ::operator new(n);}
void operator delete[](void*p)noexcept{::operator delete(p);}
void operator delete[](void*p,std::size_t)noexcept{::operator delete(p);}
#include SOURCE
int main(int argc,char**argv){
 if(argc!=2)return 1;
 const std::size_t n=std::strtoull(argv[1],nullptr,10);std::string input(n,'a');using namespace allocation_probe;tracking=true;reset();
 std::size_t ctor_calls,ctor_bytes,copy_calls,copy_bytes,assign_calls,assign_bytes,move_calls;std::uint64_t checksum=0;
 {
  RollingHash a(input,1000000007);ctor_calls=count;ctor_bytes=bytes;checksum+=a.whole();reset();
  RollingHash b=a;copy_calls=count;copy_bytes=bytes;checksum+=b.whole();reset();
  b=a;assign_calls=count;assign_bytes=bytes;checksum+=b.whole();reset();
  RollingHash c=std::move(b);b=std::move(c);move_calls=count;checksum+=b.whole();
 }
 tracking=false;if(live!=0)return 2;
 std::printf("%zu %zu %zu %zu %zu %zu %zu %zu %zu %ju\n",sizeof(RollingHash),ctor_calls,ctor_bytes,copy_calls,copy_bytes,assign_calls,assign_bytes,move_calls,live,static_cast<std::uintmax_t>(checksum));
}

