#include SOURCE
#include <algorithm>
#include <chrono>
#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <random>
#include <string>
#include <utility>
#include <vector>
int main(int argc,char**argv) {
 if(argc!=4)return 1;
 const std::size_t n=std::strtoull(argv[1],nullptr,10);const int mode=std::atoi(argv[2]);const int reps=std::atoi(argv[3]);
 std::mt19937_64 rng(61022);std::string s(n,'a'),t(n,'a');
 if(mode==0||mode==4||mode==5||mode==6||mode>=8)for(char&c:s)c=static_cast<char>(rng()%26+'a');
 if(mode==1)for(std::size_t i=0;i<n;++i)s[i]=static_cast<char>('a'+i%4);
 if(mode==2)for(std::size_t i=0;i<n;++i)s[i]=static_cast<char>('a');
 if(mode==3){for(char&c:s)c=static_cast<char>(rng()%26+'a');t=s;if(n)t[n/2]='!';}
 else t=s;
 const std::uint64_t base=1000000007;RollingHash a(s,base),b(t,base);
 std::vector<std::pair<std::size_t,std::size_t>> queries;queries.reserve(n);
 for(std::size_t i=0;i<n;++i){if(mode<=2)queries.emplace_back(0,i);else if(mode==3)queries.emplace_back(i/2,i/2);else queries.emplace_back(rng()%(n+1),rng()%(n+1));}
 std::uint64_t checksum=0;
 const auto run=[&](){
  if(mode==7){RollingHash built(s,base);checksum+=built.whole();return;}
  if(mode==8){RollingHash copy=a;checksum+=copy.whole();return;}
  for(auto[x,y]:queries){
   if(mode<=3)checksum+=a.lcp(x,b,y);
   else if(mode==4)checksum+=a.lcp(x,b,y,64);
   else if(mode==5)checksum+=a.compare(x,n,b,y,n)+1;
   else if(mode==6)checksum+=a.get(std::min(x,y),std::max(x,y));
   else if(mode==9)checksum+=a.equal(x,n,b,y,n);
   else if(mode==10)checksum+=a.concat(a.get(0,x),a.get(x,n),n-x);
  }
 };
 run();checksum=0;
 const auto begin=std::chrono::steady_clock::now();for(int r=0;r<reps;++r)run();const auto end=std::chrono::steady_clock::now();
 const auto ns=std::chrono::duration_cast<std::chrono::nanoseconds>(end-begin).count();
 std::printf("%jd %ju\n",static_cast<std::intmax_t>(ns),static_cast<std::uintmax_t>(checksum));
}

