#include SOURCE
#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <random>
#include <stdexcept>
#include <string>
#include <utility>
int main(){
 constexpr std::uint64_t mod=(std::uint64_t{1}<<61)-1;std::mt19937_64 rng(61022);std::uint64_t checks=0;
 auto check=[&](bool v){++checks;if(!v)throw std::runtime_error("RH candidate mismatch");};
 const auto multiply=[](std::uint64_t a,std::uint64_t b){std::uint64_t z=0;while(b){if(b&1)z=(z+a)%mod;a=(a+a)%mod;b>>=1;}return z;};
 for(int trial=0;trial<200;++trial){std::string s(rng()%64,'a'),t(rng()%64,'a');for(char&x:s)x=static_cast<char>(rng()%256);for(char&x:t)x=static_cast<char>(rng()%256);if(trial%4==0)t=s;if(trial%4==1){std::fill(s.begin(),s.end(),'a');t=s;if(!t.empty())t[t.size()/2]='b';}
  for(auto base:{std::uint64_t{0},std::uint64_t{2},std::uint64_t{1000000007},mod-2,mod,std::numeric_limits<std::uint64_t>::max()}){
   RollingHash a(s,base),b(t,base);const auto factor=a.base();
   for(std::size_t l=0;l<=s.size();++l){std::uint64_t hash=0;for(std::size_t r=l;r<=s.size();++r){check(a.get(l,r)==hash);const auto m=l+(r-l)/2;check(a.concat(a.get(l,m),a.get(m,r),r-m)==hash);if(r<s.size())hash=(multiply(hash,factor)+static_cast<unsigned char>(s[r]))%mod;}}
   check(a.whole()==a.get(0,s.size()));check(a.lcp(0,a,0)==s.size());
   if(base==1000000007)for(int q=0;q<100;++q){const auto l=rng()%(s.size()+1),ol=rng()%(t.size()+1),limit=rng()%80;std::size_t len=0;while(len<limit&&l+len<s.size()&&ol+len<t.size()&&s[l+len]==t[ol+len])++len;check(a.lcp(l,b,ol,limit)==len);}
  }
 }
 std::printf("PASS checks=%ju\n",static_cast<std::uintmax_t>(checks));
}

