from pathlib import Path
import subprocess,json,hashlib,fcntl,statistics
p=Path(__file__).parent;o=p/'final_api';o.mkdir(exist_ok=True);variants=['baseline','control','final'];compilers={'gcc':['g++'],'clang':['clang++','--gcc-install-dir=/opt/atcoder/gcc/lib/gcc/x86_64-pc-linux-gnu/15.3.0']};configs={'native':[],'standard':['-DSIRKIT_FORCE_STANDARD_ARITHMETIC','-U__SIZEOF_INT128__']};builds=[];sha=lambda b:hashlib.sha256(b).hexdigest()
for config,flags in configs.items():
 for v in variants:
  for cc,compiler in compilers.items():
   cmd=['taskset','-c','8',*compiler,'-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS','-DSOURCE="'+str(p/(v+'.hpp'))+'"',str(p/'api_v2.cpp'),'-o',str(o/(cc+'_'+config+'_'+v)),*flags];a=subprocess.run(cmd,capture_output=True,text=True);assert a.returncode==0,a.stderr;assert not a.stderr;builds.append(dict(variant=v,compiler=cc,config=config,command=cmd,header_sha256=sha((p/(v+'.hpp')).read_bytes()),binary_sha256=sha((o/(cc+'_'+config+'_'+v)).read_bytes())))
raw={};loops={};checksums={}
def run(cc,config,v,n,mode,count):
 a=subprocess.run(['taskset','-c','14',str(o/(cc+'_'+config+'_'+v)),str(n),str(mode),str(count)],capture_output=True,text=True);assert a.returncode==0 and not a.stderr,a.stderr;ns,check=map(int,a.stdout.split());return ns,check
with open('/tmp/atcoder_full_performance_20261018/benchmark.lock','a')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for cc in compilers:
  for config in configs:
   for n in [32,131072]:
    for mode in range(14):
     key=f'{cc}_{config}_{n}_{mode}';pilot=max(1,1000//n);ns,_=run(cc,config,'baseline',n,mode,pilot);count=max(1,int(pilot*30e6/max(1,ns)));loops[key]=count;raw[key]={v:[]for v in variants};checksums[key]={}
     for rep in range(7):
      order=variants[rep%len(variants):]+variants[:rep%len(variants)]
      for v in order:
       ns,check=run(cc,config,v,n,mode,count);raw[key][v].append(ns/1e6);checksums[key][v]=check
     assert len(set(checksums[key].values()))==1,(key,checksums[key]);med={v:statistics.median(xs)for v,xs in raw[key].items()};print(key,{v:round(x/med['baseline'],3)for v,x in med.items()},flush=True)
med={k:{v:statistics.median(ts)for v,ts in d.items()}for k,d in raw.items()};ratios={k:{v:t/d['baseline']for v,t in d.items()}for k,d in med.items()};(o/'results.json').write_text(json.dumps(dict(status='PASS',builds=builds,harness_sha256=sha((p/'api_v2.cpp').read_bytes()),raw_ms=raw,medians_ms=med,ratios=ratios,repetitions=7,loop_counts=loops,checksums=checksums,note='Native128/standard fallback, GCC/Clang, SKIP, identical operations/harness/loop counts within each condition. Input construction and queries preparation outside timing; modes7/8 measure construction/copy allocation and destruction.'),indent=2)+'\n')

