baseline=b/'String/RollingHash.cpp';variants={'baseline':baseline,'control':baseline,'final':p/'final.hpp'}if stage=='final_performance'else{'baseline':baseline,'control':baseline,'first':p/'opt/prefix_first.hpp','midfull':p/'opt/prefix_midfull.hpp','midfull_self':p/'opt/prefix_midfull_self.hpp'}
original=(b/'Verify/current/submissions/rolling_hash.cpp').read_bytes();assert original.count(baseline.read_bytes())==1
modes={'gcc':['g++'],'clang':['clang++','--gcc-install-dir=/opt/atcoder/gcc/lib/gcc/x86_64-pc-linux-gnu/15.3.0']};builds=[]
for name,src in variants.items():(o/(name+'.hpp')).write_bytes(src.read_bytes());(o/(name+'.cpp')).write_bytes(original.replace(baseline.read_bytes(),src.read_bytes(),1))
