 for name,src in variants.items():
  cmd=['taskset','-c','6',*cc,'-std=c++23','-O2',str(o/(name+'.cpp')),'-o',str(o/(mode+'_'+name))];result=subprocess.run(cmd,capture_output=True,check=True);assert not result.stderr;builds.append({'mode':mode,'variant':name,'command':cmd,'header_sha256':sha((o/(name+'.hpp')).read_bytes()),'translation_unit_sha256':sha((o/(name+'.cpp')).read_bytes()),'binary_sha256':sha((o/(mode+'_'+name)).read_bytes())})
